place.example:
const { Events, Chat } = kcds.core;

const ring = kcds.world.Marker.place('materials/decals/ring', new kcds.math.Vector3(100, 200, 10), {
  shape: 'cylinder',
  size: 3,
  color: 0x00ff00ff,
  trigger: true,
});

Events.on('markerEnter', (marker, player) => {
  if (marker.id === ring.id) {
    Chat.sendToAll(`${player.nickname} stepped in`);
  }
});

